// Event notifications (WF-19, Phase 4; mapping approved 2026-10-27).
//
//   Event                                   Recipients
//   Student application received            student (address from the form)
//   Student application validated/rejected  student
//   Company application received           company coordinator (the convenio,
//                                           when generated, is offered as attachment)
//   Company application validated/rejected  company coordinator
//   Convenio generated by the centre        company coordinator (PDF offered)
//   Document rejected                       whoever uploads it again (student
//                                           or company coordinator)
//   Reservation created                     student; also the company when the
//                                           centre made it (staff, reassignment)
//   Reservation cancelled                   student; also the company when the
//                                           centre cancelled it or a confirmation
//                                           cancelled it
//   Reservation confirmed                   student and company
//   Places reduced                          company (list of cancelled reservations)
//
// Texts: every subject and body comes from dual_correo_plantillas (migration
// 022), edited by the administrators. This file only decides when, to whom and
// with which values (correoPlantillas.CONTRATO). A template switched off sends
// nothing; a missing or invalid one sends nothing and logs an error.
// Attachments (migrations 023 and 024): whether an email carries any and which
// ones is stored with the template. This file only says which request the
// email is about (documentosDe), so the configured documents of that request
// can be read; it never attaches on its own.
//
// Rules:
// - Call only AFTER the transaction committed. Callers do not await: a
//   delivery problem is logged and never changes the API response.
// - Each function re-reads what it needs, so a stale or rolled-back caller
//   value can never be sent.
// - Emails carry names, the ciclo and the convocatoria, never DNI/NIE, phone
//   numbers or the free-text cancellation reason (SEC-11). Rejection reasons
//   are sent to the party who must correct something. Exception: the places
//   reduction summary lists the DNI of each cancelled student to the company.
// - Values are HTML-escaped by the template renderer (SEC-10).
// - Delivery mode (log / smtp) is decided in mail/config.js.
const pool = require('../db/pool');
const { defByClave } = require('./documentCatalogue');
const plantillas = require('./correoPlantillas');
const { escapeHtml } = require('../mail/plantilla');

let transporter = null;
try {
  transporter = require('../mail/config').transporter;
} catch {
  /* mail not configured */
}

const PORTAL = (process.env.APP_URL || '').replace(/\/$/, '');
const ENLACE_PORTAL = PORTAL ? `${PORTAL}/login` : '';
const COORDINADOR = 'coordinador/a';

// documentos: loader of the generated documents of the request the email is
// about (documentosDe). Whether any of them go, and which other attachments
// go, is decided by the administrators (dual_correo_adjuntos).
async function enviar(clave, to, valores, documentos = null) {
  if (!to) {
    console.warn(`[notificación] ${clave}: sin dirección de correo, no se envía.`);
    return false;
  }
  if (!transporter) {
    console.warn(`[notificación] ${clave}: correo no configurado.`);
    return false;
  }
  const correo = await plantillas.componer(clave, { enlace_portal: ENLACE_PORTAL, ...valores }, documentos);
  if (!correo) {
    console.log(`[notificación] ${clave}: desactivado por administración, no se envía.`);
    return false;
  }
  await transporter.sendMail({
    from: `"Salesianos Dual" <${process.env.EMAIL_USER}>`,
    to,
    subject: correo.asunto,
    html: correo.html,
    ...(correo.attachments?.length ? { attachments: correo.attachments } : {}),
  });
  return true;
}

// Loader for the generated documents of one request: the convenio of a company
// application (id_solicitud_empresa) or the Anexo II/III of a reservation
// (id_reserva). It reads the request's current document, the one generated
// with the active template (or the signed copy that replaced it); it never
// generates one. `generados` passes a PDF the caller has just generated.
// File name: <DOCUMENTO>_<empresa or alumno>_<year>.pdf, safe characters only.
function documentosDe({ id_solicitud_empresa = null, id_reserva = null, nombre = '' }, generados = {}) {
  const seguro = String(nombre || '').replace(/[^A-Za-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60) || 'documento';
  return async (documento) => {
    const filename = `${documento}_${seguro}_${new Date().getFullYear()}.pdf`;
    if (generados[documento]) return { filename, content: generados[documento] };
    const ambito = defByClave(documento)?.ambito;
    const [columna, id] = ambito === 'solicitud_empresa'
      ? ['id_solicitud_empresa', id_solicitud_empresa]
      : ambito === 'reserva'
        ? ['id_reserva', id_reserva]
        : [null, null];
    if (!columna || !id) return null;
    const [rows] = await pool.query(
      `SELECT d.archivo
         FROM dual_documentos d
         JOIN dual_tipos_documento td ON td.id_tipo_documento = d.id_tipo_documento
        WHERE d.${columna} = ? AND td.nombre = ? AND d.es_actual = 1 AND d.archivo IS NOT NULL
        ORDER BY d.id_documento DESC
        LIMIT 1`,
      [id, documento],
    );
    if (!rows[0]?.archivo) return null;
    return { filename, content: Buffer.isBuffer(rows[0].archivo) ? rows[0].archivo : Buffer.from(rows[0].archivo) };
  };
}

// Never throws: notifications must not affect the request that triggered them.
function safe(evento, fn) {
  return (...args) =>
    Promise.resolve()
      .then(() => fn(...args))
      .catch((err) => {
        console.error(`[notificación] ${evento}: no se pudo enviar.`, err.message);
        return false;
      });
}

// ── Data ────────────────────────────────────────────────────────────────────

async function datosSolicitudAlumno(id) {
  const [rows] = await pool.query(
    `SELECT a.nombre, a.email, c.nombre AS convocatoria, esp.nombre AS especialidad
       FROM dual_solicitudes_alumno sa
       JOIN gf_alumnosfct a ON a.idalumno = sa.id_alumno
       JOIN dual_convocatorias c ON c.id_convocatoria = sa.id_convocatoria
       LEFT JOIN dual_especialidades esp ON esp.id_especialidad = sa.id_especialidad
      WHERE sa.id_solicitud_alumno = ?`,
    [id],
  );
  return rows[0] || null;
}

async function datosSolicitudEmpresa(id) {
  const [rows] = await pool.query(
    `SELECT emp.empresa, ct.nombre AS coordinador, ct.email, c.nombre AS convocatoria
       FROM dual_solicitudes_empresa se
       JOIN ge_empresas emp ON emp.idempresa = se.id_empresa
       JOIN dual_convocatorias c ON c.id_convocatoria = se.id_convocatoria
       LEFT JOIN ge_contactos ct ON ct.idcontacto = se.id_coordinador_empresa
      WHERE se.id_solicitud_empresa = ?`,
    [id],
  );
  return rows[0] || null;
}

async function datosReserva(id) {
  const [rows] = await pool.query(
    `SELECT r.id_reserva, er.nombre AS estado,
            a.nombre AS alumno, a.email AS email_alumno,
            emp.empresa, ct.nombre AS coordinador, ct.email AS email_empresa,
            esp.nombre AS especialidad, c.nombre AS convocatoria
       FROM dual_reservas r
       JOIN dual_estados_reserva er ON er.id_estado_reserva = r.id_estado_reserva
       JOIN dual_solicitudes_alumno sa ON sa.id_solicitud_alumno = r.id_solicitud_alumno
       JOIN gf_alumnosfct a ON a.idalumno = sa.id_alumno
       JOIN dual_solicitud_empresa_especialidades ee
         ON ee.id_solicitud_empresa_especialidad = r.id_solicitud_empresa_especialidad
       JOIN dual_solicitudes_empresa se ON se.id_solicitud_empresa = ee.id_solicitud_empresa
       JOIN ge_empresas emp ON emp.idempresa = se.id_empresa
       JOIN dual_especialidades esp ON esp.id_especialidad = ee.id_especialidad
       JOIN dual_convocatorias c ON c.id_convocatoria = se.id_convocatoria
       LEFT JOIN ge_contactos ct ON ct.idcontacto = se.id_coordinador_empresa
      WHERE r.id_reserva = ?`,
    [id],
  );
  return rows[0] || null;
}

async function datosDocumento(id) {
  const [rows] = await pool.query(
    `SELECT d.id_documento, td.nombre AS clave,
            d.id_solicitud_alumno, d.id_solicitud_empresa, d.id_reserva
       FROM dual_documentos d
       JOIN dual_tipos_documento td ON td.id_tipo_documento = d.id_tipo_documento
      WHERE d.id_documento = ?`,
    [id],
  );
  return rows[0] || null;
}

// Template values for each kind of record.
const valoresAlumno = (d) => ({ alumno: d.nombre, convocatoria: d.convocatoria, ciclo: d.especialidad || 'FP Dual' });
const valoresEmpresa = (d) => ({ coordinador: d.coordinador || COORDINADOR, empresa: d.empresa, convocatoria: d.convocatoria });
const valoresReserva = (r) => ({
  alumno: r.alumno,
  coordinador: r.coordinador || COORDINADOR,
  empresa: r.empresa,
  ciclo: r.especialidad,
  convocatoria: r.convocatoria,
});

// ── Events ──────────────────────────────────────────────────────────────────

// Confirmation after the public student form. The record was just committed by
// the caller, which passes the values it inserted.
const solicitudAlumnoRecibida = safe('solicitud_alumno_recibida', async (email, nombre, convocatoria) =>
  enviar('solicitud_alumno_recibida', email, { alumno: nombre, convocatoria }));

const solicitudAlumno = safe('solicitud_alumno', async (idSolicitud, estado, motivo) => {
  if (estado !== 'VALIDADO' && estado !== 'RECHAZADO') return false;
  const d = await datosSolicitudAlumno(idSolicitud);
  if (!d) return false;
  if (estado === 'VALIDADO') return enviar('solicitud_alumno_validada', d.email, valoresAlumno(d));
  return enviar('solicitud_alumno_rechazada', d.email, { ...valoresAlumno(d), motivo });
});

// The centre corrected the ciclo of a student application.
const cicloCorregido = safe('ciclo_corregido', async (idSolicitud) => {
  const d = await datosSolicitudAlumno(idSolicitud);
  if (!d) return false;
  return enviar('ciclo_corregido', d.email, valoresAlumno(d));
});

// Administración resolved the student's request to correct their data.
const cambioDatosResuelto = safe('cambio_datos_alumno', async (idSolicitud, aprobado, motivo) => {
  const d = await datosSolicitudAlumno(idSolicitud);
  if (!d) return false;
  if (aprobado) return enviar('cambio_datos_aprobado', d.email, valoresAlumno(d));
  return enviar('cambio_datos_rechazado', d.email, { ...valoresAlumno(d), motivo });
});

const solicitudEmpresa = safe('solicitud_empresa', async (idSolicitud, estado, motivo) => {
  if (estado !== 'VALIDADO' && estado !== 'RECHAZADO') return false;
  const d = await datosSolicitudEmpresa(idSolicitud);
  if (!d) return false;
  if (estado === 'VALIDADO') {
    return enviar('solicitud_empresa_validada', d.email, valoresEmpresa(d),
      documentosDe({ id_solicitud_empresa: idSolicitud, nombre: d.empresa }));
  }
  return enviar('solicitud_empresa_rechazada', d.email, { ...valoresEmpresa(d), motivo });
});

// Confirmation after the public form or a reapplication. Sent whether or not the
// convenio could be generated: without one the company is told the convenio
// will appear in the portal once the centre generates it.
const solicitudEmpresaRecibida = safe('solicitud_empresa_recibida', async (idSolicitud, pdf = null) => {
  const d = await datosSolicitudEmpresa(idSolicitud);
  if (!d) return false;
  const documentos = documentosDe({ id_solicitud_empresa: idSolicitud, nombre: d.empresa }, pdf ? { CONVENIO: pdf } : {});
  // A reapplication may already have its convenio from before.
  const generado = Boolean(pdf) || Boolean(await documentos('CONVENIO'));
  return enviar(
    'solicitud_empresa_recibida',
    d.email,
    { ...valoresEmpresa(d), convenio_generado: generado ? 'sí' : '' },
    documentos,
  );
});

// The centre generated (or regenerated) the convenio after the application.
const convenioDisponible = safe('convenio_disponible', async (idSolicitud, pdf = null) => {
  const d = await datosSolicitudEmpresa(idSolicitud);
  if (!d) return false;
  return enviar('convenio_disponible', d.email, valoresEmpresa(d),
    documentosDe({ id_solicitud_empresa: idSolicitud, nombre: d.empresa }, pdf ? { CONVENIO: pdf } : {}));
});

const documentoRechazado = safe('documento_rechazado', async (idDocumento, motivo) => {
  const doc = await datosDocumento(idDocumento);
  if (!doc) return false;
  const documento = defByClave(doc.clave)?.nombre || doc.clave;
  if (doc.id_solicitud_alumno) {
    const d = await datosSolicitudAlumno(doc.id_solicitud_alumno);
    if (!d) return false;
    return enviar('documento_rechazado_alumno', d.email, { ...valoresAlumno(d), documento, motivo });
  }
  if (doc.id_solicitud_empresa) {
    const d = await datosSolicitudEmpresa(doc.id_solicitud_empresa);
    if (!d) return false;
    return enviar('documento_rechazado_empresa', d.email, { ...valoresEmpresa(d), documento, motivo },
      documentosDe({ id_solicitud_empresa: doc.id_solicitud_empresa, nombre: d.empresa }));
  }
  if (doc.id_reserva) {
    // Reservation documents (Anexo II/III, Calendario) are uploaded by the company.
    const r = await datosReserva(doc.id_reserva);
    if (!r) return false;
    return enviar('documento_rechazado_reserva', r.email_empresa, { ...valoresReserva(r), documento, motivo },
      documentosDe({ id_reserva: doc.id_reserva, nombre: r.alumno }));
  }
  return false;
});

const reservaCreada = safe('reserva_creada', async (idReserva, { porCentro = false } = {}) => {
  const r = await datosReserva(idReserva);
  if (!r) return false;
  const documentos = documentosDe({ id_reserva: idReserva, nombre: r.alumno });
  const envios = [enviar('reserva_creada_alumno', r.email_alumno, valoresReserva(r), documentos)];
  if (porCentro) envios.push(enviar('reserva_creada_empresa', r.email_empresa, valoresReserva(r), documentos));
  await Promise.all(envios);
  return true;
});

const reservaCancelada = safe('reserva_cancelada', async (idReserva, { avisarEmpresa = false, avisarAlumno = true } = {}) => {
  const r = await datosReserva(idReserva);
  if (!r) return false;
  const envios = [];
  if (avisarAlumno) envios.push(enviar('reserva_cancelada_alumno', r.email_alumno, valoresReserva(r)));
  if (avisarEmpresa) envios.push(enviar('reserva_cancelada_empresa', r.email_empresa, valoresReserva(r)));
  await Promise.all(envios);
  return true;
});

const reservaConfirmada = safe('reserva_confirmada', async (idReserva) => {
  const r = await datosReserva(idReserva);
  if (!r) return false;
  const documentos = documentosDe({ id_reserva: idReserva, nombre: r.alumno });
  await Promise.all([
    enviar('reserva_confirmada_alumno', r.email_alumno, valoresReserva(r), documentos),
    enviar('reserva_confirmada_empresa', r.email_empresa, valoresReserva(r), documentos),
  ]);
  return true;
});

// Places of a ciclo reduced: pending reservations were cancelled. The caller
// passes the committed summary (the cancelled rows no longer count as active).
const cupoReducido = safe('cupo_reducido_empresa', async ({ email, empresa, especialidad, cantidadAnterior, cantidadNueva, canceladas }) =>
  enviar('cupo_reducido_empresa', email, {
    empresa,
    ciclo: especialidad,
    plazas_antes: String(Number(cantidadAnterior)),
    plazas_despues: String(Number(cantidadNueva)),
    reservas_canceladas: canceladas.map(
      (c) => `Reserva #${c.id_reserva} — ${c.alumno || 'alumno'} (${c.dni_alumno || 'sin DNI'}) · ${c.especialidad || especialidad}`,
    ),
  }));

// Password reset link (passwordResetService). Sent to whoever asked, never logged in full.
const restablecerContrasena = safe('restablecer_contrasena', async (to, nombre, link) =>
  enviar('restablecer_contrasena', to, { nombre: nombre || '', enlace: link }));

module.exports = {
  restablecerContrasena,
  solicitudAlumnoRecibida,
  solicitudAlumno,
  cicloCorregido,
  cambioDatosResuelto,
  solicitudEmpresa,
  solicitudEmpresaRecibida,
  convenioDisponible,
  documentoRechazado,
  reservaCreada,
  reservaCancelada,
  reservaConfirmada,
  cupoReducido,
  escapeHtml,
};
